 seq=[]
 # Treat header rows as palettes with zero gaps separating sequences.
 for r in (grid[0],grid[-1]):
  run=[]
  for v in r+[0]:
   if v: run.append(v)
   elif run: seq.append(run); run=[]
 for y,row in enumerate(grid):
  if y in (0,h-1): continue
  for x,v in enumerate(row):
   if v:
    p=next((p for p in seq if v in p),None)
    if p:
     left=x-p.index(v)
     for k,c in enumerate(p):
      if 0<=left+k<w: out[y][left+k]=c
    # Continue to additional separate markers in the same row.
 return out
